package com.example.mareaswatch.data
import kotlinx.coroutines.*
import java.util.Date
class MarineRepository { suspend fun load(lat:Double,lon:Double):MarineWeatherData=coroutineScope { val wa=async{ApiProvider.weather.forecast(lat,lon)}; val ma=async{ApiProvider.marine.marine(lat,lon)}; val ga=async{runCatching{ApiProvider.geo.reverse(lat=lat,lon=lon)}.getOrNull()}; val w=wa.await();val m=ma.await();val g=ga.await();val wc=w.current;val mc=m.current;val a=g?.address;val place=listOfNotNull(a?.amenity,a?.suburb,a?.town,a?.city,a?.municipality,a?.county).firstOrNull()?"Costa local";val region=a?.state?:a?.country; MarineWeatherData(lat,lon,if(region.isNullOrBlank())place else "$place, $region",wc?.temperature_2m?:0.0,wc?.apparent_temperature?:0.0,wc?.wind_speed_10m?:0.0,wc?.wind_direction_10m?:0.0,wc?.wind_gusts_10m?:0.0,wc?.surface_pressure?:0.0,wc?.relative_humidity_2m?:0,wc?.uv_index?:0.0,w.hourly?.precipitation_probability?.firstOrNull()?:0,mc?.wave_height?:0.0,mc?.wave_period?:0.0,mc?.wave_direction?:0.0,mc?.swell_wave_height?:0.0,w.daily?.sunrise?.firstOrNull()?.takeLast(5)?:"--:--",w.daily?.sunset?.firstOrNull()?.takeLast(5)?:"--:--",TideCalculator.generate(lat,lon,Date())) } }
